define(['jquery', 'core/ajax', 'core/chartjs'], function($, Ajax, Chart) {
    let userChart, enrolChart,registeredChart,webMobileChart, data = {};

  

    function renderUserChart(range, data) {
        if (userChart) userChart.destroy();

        let labels = [];
        let chartData = [];

        const rangeMap = {
            "1day": 0,
            "7day": 1,
            "30day": 2,
            "1year": 3
        };
        const idx = rangeMap[range];
        const dataset = data.loggedin[idx] || [];

        console.log("Rendering chart for:", range, dataset);

        if (range === "1day") {
            let now = new Date(), h = now.getHours();
            for (let i = 0; i <= h; i++) {
                let hour = (i % 12 === 0) ? 12 : i % 12;
                let ampm = i < 12 ? "AM" : "PM";
                labels.push(hour + " " + ampm);
                chartData.push(dataset[i] ?? 0);
            }

        } else if (range === "7day") {
            let today = new Date();
            for (let i = 0; i < 7; i++) {
                let d = new Date(today);
                d.setDate(today.getDate() - (6 - i));
                labels.push(d.toLocaleDateString("en-GB",{day:"2-digit",month:"short"}));
                chartData.push(dataset[i] ?? 0);
            }

        } else if (range === "30day") {
            for (let i = 0; i < 4; i++) {
                labels.push("Week " + (i+1));
                chartData.push(dataset[i] ?? 0);
            }

        } else if (range === "1year") {
            const months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
            for (let i = 0; i < 12; i++) {
                labels.push(months[i]);
                chartData.push(dataset[i] ?? 0);
            }
        }

        const ctx = document.getElementById("userChart").getContext("2d");
        const gradient = ctx.createLinearGradient(0,0,0,400);
        gradient.addColorStop(0,"rgba(54,162,235,0.9)");
        gradient.addColorStop(1,"rgba(54,162,235,0.2)");

        userChart = new Chart(ctx, {
            type: "bar",
            data: {
                labels: labels,
                datasets: [{
                    label: "Users (" + range + ")",
                    data: chartData,
                    backgroundColor: gradient,
                    borderColor: "rgba(54,162,235,1)",
                    borderWidth: 1,
                    borderRadius: 8
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: { display: true }
                },
                scales: {
                    y: {
                        beginAtZero: true,
                        grid: { color: "rgba(200,200,200,0.2)" },
                        ticks: { color: "#444", font: { size: 12 } },
                        title: { display: true, text: "Logged-in Users", color: "#000" }
                    },
                    x: {
                        grid: { color: "rgba(200,200,200,0.1)" },
                        ticks: { color: "#444", font: { size: 12 } },
                        title: { display: true, text: range, color: "#000" }
                    }
                }
            }
        });
    }


    function renderEnrolChart(range, data) {
        if (enrolChart) enrolChart.destroy();

        let labels = [];
        let chartData = [];

        const rangeMap = {
            "1day": 0,
            "7day": 1,
            "30day": 2,
            "1year": 3
        };
        const idx = rangeMap[range];
        const dataset = data.enrolments[idx] || [];

        console.log("Rendering enrol chart for:", range, dataset);

        if (range === "1day") {
            let now = new Date(), h = now.getHours();
            for (let i = 0; i <= h; i++) {
                let hour = (i % 12 === 0) ? 12 : i % 12;
                let ampm = i < 12 ? "AM" : "PM";
                labels.push(hour + " " + ampm);
                chartData.push(dataset[i] ?? 0);
            }

        } else if (range === "7day") {
            let today = new Date();
            for (let i = 0; i < 7; i++) {
                let d = new Date(today);
                d.setDate(today.getDate() - (6 - i));
                labels.push(d.toLocaleDateString("en-GB", { day: "2-digit", month: "short" }));
                chartData.push(dataset[i] ?? 0);
            }

        } else if (range === "30day") {
            for (let i = 0; i < 4; i++) {
                labels.push("Week " + (i + 1));
                chartData.push(dataset[i] ?? 0);
            }

        } else if (range === "1year") {
            const months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
            for (let i = 0; i < 12; i++) {
                labels.push(months[i]);
                chartData.push(dataset[i] ?? 0);
            }
        }

        const ctx = document.getElementById('enrolChart').getContext('2d');
        const gradient = ctx.createLinearGradient(0,0,0,400);
        gradient.addColorStop(0,"rgba(76,175,80,0.9)");
        gradient.addColorStop(1,"rgba(76,175,80,0.2)");

        enrolChart = new Chart(ctx, {
            type: 'line',
            data: { 
                labels: labels, 
                datasets: [{
                    label:'Enrolments ('+range+')',
                    data: chartData,
                    borderColor:'#4CAF50',
                    backgroundColor: gradient,
                    fill:true, 
                    tension:0.4
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: { display: true }
                },
                scales: {
                    y: {
                        beginAtZero: true,
                        grid: { color: "rgba(200,200,200,0.2)" },
                        ticks: { color: "#444", font: { size: 12 } },
                        title: { display: true, text: "Registered Users", color: "#000" }
                    },
                    x: {
                        grid: { color: "rgba(200,200,200,0.1)" },
                        ticks: { color: "#444", font: { size: 12 } },
                        title: { display: true, text: range, color: "#000" }
                    }
                }
            }
        });
    }


    function renderRegisteredChart(range, data) {
        if (registeredChart) registeredChart.destroy();

        let labels = [];
        let chartData = [];

        // Map range -> index in API array
        const rangeMap = {
            "1day": 0,
            "7day": 1,
            "30day": 2,
            "1year": 3
        };
        const idx = rangeMap[range];
        const dataset = data.registered[idx] || [];

        console.log("Rendering registered chart for:", range, dataset);

        if (range === "1day") {
            let now = new Date(), h = now.getHours();
            for (let i = 0; i <= h; i++) {
                let hour = (i % 12 === 0) ? 12 : i % 12;
                let ampm = i < 12 ? "AM" : "PM";
                labels.push(hour + " " + ampm);
                chartData.push(dataset[i] ?? 0);
            }

        } else if (range === "7day") {
            let today = new Date();
            for (let i = 0; i < 7; i++) {
                let d = new Date(today);
                d.setDate(today.getDate() - (6 - i));
                labels.push(d.toLocaleDateString("en-GB", { day: "2-digit", month: "short" }));
                chartData.push(dataset[i] ?? 0);
            }

        } else if (range === "30day") {
            for (let i = 0; i < 4; i++) {
                labels.push("Week " + (i + 1));
                chartData.push(dataset[i] ?? 0);
            }

        } else if (range === "1year") {
            const months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
            for (let i = 0; i < 12; i++) {
                labels.push(months[i]);
                chartData.push(dataset[i] ?? 0);
            }
        }

        const ctx = document.getElementById("registeredChart").getContext("2d");
        const gradient = ctx.createLinearGradient(0,0,0,400);
        gradient.addColorStop(0,"rgba(58,123,213,0.9)");
        gradient.addColorStop(1,"rgba(0,210,255,0.6)");

        registeredChart = new Chart(ctx, {
            type: "bar",
            data: {
                labels: labels,
                datasets: [{
                    label: "Registered Users (" + range + ")",
                    data: chartData,
                    backgroundColor: gradient,
                    borderColor: "rgba(58,123,213,1)",
                    borderWidth: 2,
                    borderRadius: 8,
                    barPercentage: 0.6,
                    categoryPercentage: 0.8,
                    hoverBackgroundColor: "rgba(0,210,255,0.9)"
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: {
                        display: true,
                        labels: {
                            color: "#333",
                            font: { size: 13, weight: "bold" }
                        }
                    },
                    tooltip: {
                        backgroundColor: "#222",
                        titleColor: "#fff",
                        bodyColor: "#fff",
                        borderColor: "#00d2ff",
                        borderWidth: 1,
                        padding: 10
                    }
                },
                scales: {
                    y: {
                        beginAtZero: true,
                        grid: { color: "rgba(200,200,200,0.2)" },
                        ticks: { color: "#444", font: { size: 12 } },
                        title: { display: true, text: "Registered Users", color: "#000" }
                    },
                    x: {
                        grid: { color: "rgba(200,200,200,0.1)" },
                        ticks: { color: "#444", font: { size: 12 } },
                        title: { display: true, text: range, color: "#000" }
                    }
                }
            }
        });
    }
    function renderWebMobileChart(range, data) {
        if (webMobileChart) webMobileChart.destroy();

        const dataset = data.webmobile[range] || {};
        let web = dataset.web ?? 0;
        let mobile = dataset.mobile ?? 0;

        // Gradient colors
        const ctx = document.getElementById("webMobileChart").getContext("2d");
        let gradientWeb = ctx.createLinearGradient(0, 0, 0, 250);
        gradientWeb.addColorStop(0, "#93C5FD");
        gradientWeb.addColorStop(1, "#3B82F6");

        let gradientMobile = ctx.createLinearGradient(0, 0, 0, 250);
        gradientMobile.addColorStop(0, "#6EE7B7");
        gradientMobile.addColorStop(1, "#10B981");

        webMobileChart = new Chart(ctx, {
            type: "doughnut",
            data: {
                labels: ["Web", "Mobile"],
                datasets: [{
                    data: [web, mobile],
                    backgroundColor: [gradientWeb, gradientMobile],
                    borderWidth: 4,
                    borderColor: "#ffffff",
                    hoverOffset: 14
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                cutout: "82%",
                plugins: {
                    legend: {
                        position: "bottom",
                        labels: {
                            font: { size: 14, family: "'Inter', sans-serif", weight: "600" },
                            color: "#374151",
                            usePointStyle: true,
                            pointStyle: "circle",
                            padding: 18
                        }
                    },
                    tooltip: {
                        backgroundColor: "#111827",
                        titleFont: { size: 13, weight: "600" },
                        bodyFont: { size: 12 },
                        padding: 10,
                        cornerRadius: 8,
                        callbacks: {
                            label: function(context) {
                                let total = web + mobile;
                                let value = context.parsed;
                                let percent = total > 0 ? ((value / total) * 100).toFixed(1) : 0;
                                return `${context.label}: ${value} (${percent}%)`;
                            }
                        }
                    }
                },
                animation: {
                    animateRotate: true,
                    animateScale: true,
                    duration: 1200,
                    easing: "easeOutQuart"
                }
            },
            plugins: [
                {
                    id: "centerText",
                    beforeDraw: function(chart) {
                        let { width, height } = chart;
                        let ctx = chart.ctx;
                        ctx.restore();

                        ctx.font = "bold " + (height / 9) + "px 'Inter', sans-serif";
                        ctx.fillStyle = "#111827";
                        ctx.textBaseline = "middle";
                        let total = web + mobile;
                        let text = total + " Users";
                        let textX = (width - ctx.measureText(text).width) / 2;
                        let textY = height / 2 - 10;
                        ctx.fillText(text, textX, textY);

                        ctx.font = "normal " + (height / 18) + "px 'Inter', sans-serif";
                        ctx.fillStyle = "#6B7280";
                        let subText = "Web & Mobile";
                        let subTextX = (width - ctx.measureText(subText).width) / 2;
                        let subTextY = height / 2 + 30;
                        ctx.fillText(subText, subTextX, subTextY);

                        ctx.save();
                    }
                },
                {
                    id: "shadowEffect",
                    beforeDatasetsDraw(chart) {
                        let ctx = chart.ctx;
                        ctx.save();
                        ctx.shadowColor = "rgba(0, 0, 0, 0.15)";
                        ctx.shadowBlur = 12;
                        ctx.shadowOffsetX = 0;
                        ctx.shadowOffsetY = 6;
                    },
                    afterDatasetsDraw(chart) {
                        chart.ctx.restore();
                    }
                }
            ]
        });
    }



    function loadData(range) {
        Ajax.call([{
            methodname: 'local_edzdashboardview_get_user_dashboard_data',
            args: { range: range}
        }])[0].done(function(resp) {
            data = resp;

            console.log("Data loaded for range:", range, resp);
            const rangeMap = { "1day":0, "7day":1, "30day":2, "1year":3 };
            const idx = rangeMap[range];


            console.log("Range:", range, "Index:", idx);
            console.log("Response cards:", resp.cards.activeusers, resp.cards.enrolments);
            console.log("Response data:", resp.cards.activeusers[idx]);

            // ✅ Update cards correctly
            $('#card-active').text("TEST");

            $('#card-activeuser').html(resp.cards.activeusers[idx] ?? 0);
            $('#card-enroluser').html(resp.cards.enrolments[idx] ?? 0);
            $('#card-registereduser').html(resp.cards.registeredusers[idx] ?? 0);
            const rangeMap1 = { "1day": "1day", "7day": "7day", "30day": "30day", "1year": "1year" };
            const webMobile = resp.webmobile[rangeMap1[range]] ?? { web: 0, mobile: 0 };

            const totalUsers = (webMobile.web ?? 0) + (webMobile.mobile ?? 0);

            $('#card-webmobileuser').html(totalUsers);

            $(document).ready(function() {
                $('#card-active').html(resp.cards.activeusers[idx] ?? 0);
            });

            // Render charts
            renderUserChart(range,data);
            renderEnrolChart(range,data);
            renderRegisteredChart(range,data);
            renderWebMobileChart(range,data);
        });
    }

    return {
        init: function() {
            console.log("✅ user.js init called");
            // Default load with 1day
            loadData('1day');

            console.log("Binding range selection events");

            // Bind change event for user selection
            $('input[name="range-users"]').on('change', function() {
                let range = $(this).val();
                loadData(range);
            });
        }
    };
});
